function passwordSettings(){
 const panel=document.createElement('form');panel.id='password-form';panel.className='panel mt';
 panel.innerHTML=`<h3>Change password</h3><div class="grid three">${field('current','Current password','','password','required autocomplete="current-password"')}${field('new-password','New password','','password','required minlength="10" maxlength="256" autocomplete="new-password"')}${field('confirm-password','Confirm new password','','password','required minlength="10" autocomplete="new-password"')}</div><p class="field-hint">Changing your password signs out your other sessions.</p><p class="form-error" role="alert"></p><button class="primary">Update Password</button>`;
 $('#page').append(panel);panel.onsubmit=async e=>{e.preventDefault();const d=formData(panel);const error=$('.form-error',panel);error.textContent='';if(d['new-password']!==d['confirm-password']){error.textContent='Passwords do not match.';return;}const b=$('button',panel);b.disabled=true;try{await api('/api/change-password','POST',{current:d.current,password:d['new-password']});panel.reset();toast('Password updated. Other sessions signed out.');}catch(e){error.textContent=e.message;}finally{b.disabled=false;}};
}
function legalPage(kind){const pages={about:{title:'A Free Toolkit for Players',intro:'Felt & Fortune brings free blackjack training, simulation, and results tracking together in one place.',sections:[['The project','Practice blackjack decisions, run configurable simulations, track your results, and collaborate with other players. Accounts are free and no payment method is collected.'],['Independent implementation','Felt & Fortune is an independent student project. AP Toolbox and Blackjack.tools inform the feature research. All training logic, calculations, and community features here use our own implementation.'],['Transparent results','The directory and forum begin empty. Users supply their own observations. Calculator results come from the selected simulation settings, and estimates display their uncertainty.']]},privacy:{title:'Privacy Policy',intro:'This notice describes the local application’s implemented data handling. The site operator must add their contact information and review this policy before public launch.',sections:[['Account data','The application stores your username, email address, and a salted scrypt password hash. It uses an HttpOnly session cookie to keep you signed in. Passwords are never stored in plaintext.'],['Your records','Personal bankrolls and their sessions are restricted to you. Shared bankroll members can view their shared records. Editors may add and edit their own sessions; owners manage the bankroll and membership.'],['Community and messages','Forum posts, directory entries, reviews, and career leaderboard usernames are visible to other signed-in users. Private messages are available to their sender and recipient. The server operator can access its database and should protect backups.'],['External content','The homepage uses artwork bundled with this application. This application includes no advertising or analytics trackers.'],['Retention and requests','Records remain in the application database until removed. Sessions expire after 14 days; reset links expire after 30 minutes. Before public launch, the operator must publish a contact method for access, correction, export, and deletion requests.']]},terms:{title:'Terms of Use',intro:'These are provisional terms for this independently developed free application. The operator must review and finalize them, including operator identity and jurisdiction, before public launch.',sections:[['Free access','All implemented features are free to end users. There are no subscription plans, trial expiration dates, or payment requirements.'],['Your account','Keep your credentials private and submit only information you are authorized to share. Do not impersonate other users, abuse community features, or attempt to access other users’ private records.'],['Training and simulations','Exercises and simulations are educational tools. Results depend on the documented rules and assumptions. Simulated EV is an estimate, not a promise of financial results. This application does not accept wagers or execute gambling transactions.'],['User contributions','You retain responsibility for your posts, messages, reviews, and game reports. Do not submit private third-party information or present fabricated reports as real observations.'],['Independent project','Felt & Fortune is an independent educational project. The operator will finalize these terms and contact details before public launch.']]}};const p=pages[kind];$('#app').innerHTML=navbar()+`<main id="main" class="legal-page"><a href="/">← Back to Home</a><h1 class="mt">${p.title}</h1><p>${p.intro}</p>${p.sections.map(([t,b])=>`<h2>${t}</h2><p>${b}</p>`).join('')}${kind==='about'?'<a class="button primary mt" href="/auth/signup">Create a Free Account →</a>':''}</main>`+footer();}
function go(url){history.pushState({},'',url);render();}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||a.target||a.download)return;const url=new URL(a.href,location.href);if(url.origin!==location.origin)return;e.preventDefault();if(url.pathname===location.pathname&&url.search===location.search&&url.hash){history.pushState({},'',url);document.getElementById(decodeURIComponent(url.hash.slice(1)))?.scrollIntoView({behavior:'smooth'});$('.navlinks')?.classList.remove('open');$('#nav-menu')?.setAttribute('aria-expanded','false');return;}go(url.pathname+url.search+url.hash);});
window.addEventListener('popstate',()=>render());
function toolTiles(){return '';}
function navbar(){return `<nav class="topnav" aria-label="Main navigation">${brand()}<div class="nav-actions">${user?`<a class="button primary small" href="${paths.learn}">Open Felt &amp; Fortune</a>`:`<a class="button ghost small login-link" href="/auth/login">Log in</a><a class="button primary small" href="/start">Get started</a>`}</div></nav>`;}
function footer(){return `<footer class="footer"><div class="footer-grid">${brand()}<p>Free blackjack lessons and training tools. Educational only: no wagering, deposits, or payments.</p><div class="footer-links"><a href="/about">About</a><a href="/privacy">Privacy</a><a href="/terms">Terms</a></div></div><div class="copyright">© 2026 Felt &amp; Fortune</div></footer>`;}

// ---- public homepage (signed-in visitors go straight to Learn) ---------------------------------
function heroPath(){const nodes=[['done','check',0],['done','check',54],['current','star',72],['locked','lock',40],['locked','lock',-14]];return `<div class="hero-path c-blue"><div class="hp-top"><div class="hp-banner"><small>Unit 2</small><strong>Hard Totals</strong></div><div class="stat-strip"><span class="chip streak lit">${g('flame')}<b>12</b></span><span class="chip xp">${g('bolt')}<b>340</b></span></div></div>${nodes.map(([st,ic,x])=>`<div class="node-row" style="--x:${x}px">${st==='current'?'<span class="start-bubble">Start</span>':''}<span class="node ${st}">${g(ic)}${st==='current'?'<span class="ring"></span>':''}</span>${st==='current'?`<div class="node-ace" style="--side:-1">${ace('happy','ace-sm bob')}</div>`:''}</div>`).join('')}</div>`;}
function homepage(){
$('#app').innerHTML=navbar()+`<main id="main" class="landing"><section class="hero"><div class="hero-layout"><div class="hero-copy"><span class="pill">Free · Personalized · Bite-sized</span><h1>From your first hand<span>to playing like a pro.</span></h1><p class="lead">Answer ten quick questions. Ace, your coach, builds a path of short, interactive lessons with real training tools built in, from table basics to advantage play.</p><div class="hero-actions"><a class="button primary chunky large" href="/start">Get started</a><a class="button chunky large" href="/auth/login">I have an account</a></div><p class="byline">No subscription. No trial clock. No wagering.</p></div><figure class="hero-art" aria-hidden="true">${heroPath()}</figure></div></section>
<section class="section how" id="how"><div class="container">${sectionHead('How it works','Learn it. Drill it. Prove it.','Every lesson teaches one idea, then has you use the real tool. Practice any skill on its own whenever you like.')}<div class="grid three how-steps">${[['1','Find your level','Ten questions, including four real blackjack checks, place you on the path.','blue'],['2','Learn by doing','Lessons mix short explanations with live hands, flashing cards, and a 3D discard tray.','green'],['3','Sharpen and prove it','Drill any skill in Practice, then take on the Shoe Challenge leaderboard.','orange']].map(([n,t,d,c])=>`<div class="panel how-step c-${c}"><span class="how-num">${n}</span><h3>${t}</h3><p>${d}</p></div>`).join('')}</div></div></section>
<section class="section" id="tools"><div class="container">${sectionHead('The toolkit','Seven tools, each with one job','Use them inside lessons, or on their own from the Practice tab.')}<div class="tool-cards public">${TOOLS.map(t=>`<div class="tool-card c-${t.color}"><span class="tool-icon">${g(t.glyph)}</span><span class="tool-copy"><strong>${t.name}</strong><span>${t.purpose}</span></span></div>`).join('')}</div><p style="text-align:center;margin-top:32px"><a class="button primary chunky large" href="/start">Find my starting point</a></p></div></section>
<section class="section" id="faq"><div class="container">${sectionHead('','Questions','')}<div class="faq">${[['Is it really free?','Yes. There are no subscriptions, trials, or payments.'],['Is this gambling?','No. Felt & Fortune never takes a bet or any money. It teaches strategy and the math of risk.'],['I already know basic strategy. Do I start over?','No. The placement questions test what you know, and you skip the units you prove.'],['Which counting system is taught?','Hi‑Lo: 2–6 count +1, 7–9 count 0, and tens and aces count −1.'],['Is card counting legal?','Counting in your head is legal in most places, but casinos can refuse your play. Using a device to count is illegal in many places.'],['Does it work on my phone?','Yes. Every lesson and tool is built for touch and small screens.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div></section></main>`+footer();}

// ---- the app shell ---------------------------------------------------------------------------
const TABS=[['learn','path','Learn','/learn'],['practice','dumbbell','Practice','/practice'],['track','chart','Track','/track'],['community','users','Community','/community'],['profile','person','Profile','/profile']];
function appShell(tab){
 if($('#app .app-shell')){$$('.rail-link').forEach(a=>{const on=a.dataset.tab===tab;a.classList.toggle('active',on);on?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});$('#page').innerHTML='<div class="loading"><span class="spinner"></span>Loading…</div>';return;}
 $('#app').innerHTML=`<div class="app-shell"><aside class="learn-rail" aria-label="Main navigation">${brand()}<nav>${TABS.map(([k,gl,label,href])=>`<a href="${href}" data-tab="${k}" class="rail-link ${tab===k?'active':''}" ${tab===k?'aria-current="page"':''}>${g(gl)}<span>${label}</span></a>`).join('')}</nav><div class="rail-foot"><button type="button" class="icon-btn" id="feedback-btn" aria-label="Send feedback" title="Send feedback">${g('chat')}</button><button type="button" class="icon-btn sound-toggle" aria-pressed="${Sound.on}" aria-label="${Sound.on?'Turn sound off':'Turn sound on'}">${g(Sound.on?'speaker':'mute')}</button></div></aside><main id="main" class="app-content"><div id="page"><div class="loading"><span class="spinner"></span>Loading…</div></div></main></div>`;
 $$('.sound-toggle').forEach(b=>b.onclick=()=>{const on=Sound.toggle();b.setAttribute('aria-pressed',on);b.innerHTML=g(on?'speaker':'mute');});
 $('#feedback-btn').onclick=()=>openFeedback();
}
function openFeedback(area){const tab=location.pathname.split('/')[1];const guess=area||({learn:'lesson',practice:'practice',track:'track',community:'community'}[tab]||'other');modal('Send feedback',`<p class="muted">This goes straight to the developer. Thank you for helping test Felt &amp; Fortune!</p><div class="field"><span class="label-like">How easy was it to use?</span><div class="rating-row" role="radiogroup" aria-label="Rating from 1 to 5">${[1,2,3,4,5].map(n=>`<label class="rating-pick"><input type="radio" name="rating" value="${n}" required><span>${n}</span></label>`).join('')}</div><p class="field-hint">1 = very hard · 5 = very easy</p></div>${select('area','What were you doing?',[['signup','Signing up / the survey'],['lesson','A lesson'],['practice','A practice tool'],['track','Tracking results'],['community','Community'],['other','Something else']],guess)}${textarea('comment','What worked, and what got in your way?','','maxlength="2000" rows="4" placeholder="Anything confusing, slow, or broken?"')}`,async data=>{await api('/api/feedback','POST',{rating:Number(data.rating),area:data.area,comment:data.comment,page:location.pathname});toast('Thanks! Feedback sent.');},'Send');}
function subTabs(items,active){return `<nav class="segmented page-tabs" aria-label="Sections">${items.map(([href,label])=>`<a href="${href}" role="tab" aria-selected="${href===active}" ${href===active?'aria-current="page"':''}>${label}</a>`).join('')}</nav>`;}
function withTabs(items,active){const tabs=subTabs(items,active);const p=$('#page');const obs=new MutationObserver(()=>{if(!p.querySelector('.page-tabs'))p.insertAdjacentHTML('afterbegin',tabs);});obs.observe(p,{childList:true});cleanup=(prev=>()=>{prev();obs.disconnect();})(cleanup);}

// ---- Profile -------------------------------------------------------------------------------
async function profilePage(){
 const [stats,pathState]=await Promise.all([api('/api/practice/stats'),api('/api/path?day='+localDate())]);
 const rows=TOOLS.filter(t=>!['simulator'].includes(t.id)).map(t=>{const s=stats.tools[t.id];const v=t.id==='challenge'?(s?.sessions?`Best ${s.best} · ${s.sessions} runs`:'—'):(s?.questions?`${Math.round(s.correct/s.questions*100)}% · ${s.questions} answered · best streak ${s.best_streak}`:'—');return `<a class="profile-row c-${t.color}" href="/practice/${t.id}"><span class="tool-icon sm">${g(t.glyph)}</span><span>${t.name}</span><b>${v}</b></a>`;}).join('');
 const st=pathState.stats;
 $('#page').innerHTML=`<header class="page-hero"><div class="profile-id"><span class="avatar big">${esc(user.username[0].toUpperCase())}</span><div><h1>${esc(user.username)}</h1><p>${esc(user.email)}</p></div></div><div class="flex"><button class="small" id="profile-feedback">${g('chat')} Send feedback</button><button class="ghost" id="logout">Sign out</button></div></header>
 ${st?`<div class="plan-grid four">${[['orange','Day streak',st.streak,'flame'],['yellow','Total XP',st.xp,'bolt'],['blue','Lessons',`${st.done}/${st.total}`,'star'],['purple','Level',esc(pathState.plan.level),'trophy']].map(([c,l,v,ic])=>`<div class="stat-tile ${c}"><small>${l}</small><strong>${g(ic)} ${v}</strong></div>`).join('')}</div>`:''}
 <section class="panel mt"><h3>Practice record</h3><div class="profile-rows">${rows}</div></section>
 <form class="panel mt" id="profile-form"><h3>Account</h3><div class="grid two">${field('username','Username',user.username,'text','required minlength="3" maxlength="30"')}${field('email','Email address',user.email,'email','disabled')}</div><p class="form-error" role="alert"></p><button class="primary">Save</button></form>`;
 passwordSettings();
 $('#profile-form').onsubmit=async e=>{e.preventDefault();try{const result=await api('/api/profile','PATCH',formData(e.target));user=result.user;toast('Profile saved.');render();}catch(error){$('.form-error',e.target).textContent=error.message;}};
 $('#logout').onclick=async()=>{await api('/api/logout','POST');user=null;go('/');};
 $('#profile-feedback').onclick=()=>openFeedback();
}
const ctxBase={$,$$,esc,api,go,brand,paths,localDate,toast,getUser:()=>user,setUser:u=>{user=u;},onCleanup:fn=>{const prev=cleanup;cleanup=()=>{prev();fn();};}};
const learn=createLearn(ctxBase);
const practice=createPractice(ctxBase);
const simulator=createSimulator(ctxBase);
function needLogin(path){if(user)return false;sessionStorage.setItem('after-login',path);history.replaceState({},'','/auth/login');authPage('login');return true;}
function notFound(){$('#app').innerHTML=navbar()+`<main class="legal-page" id="main">${empty('Page not found','That page moved or doesn’t exist.',`<a class="button primary" href="${user?paths.learn:'/'}">${user?'Go to Learn':'Go home'}</a>`)}</main>`;}
async function render(){
 const version=++routeVersion;requestController.abort();requestController=new AbortController();cleanup();cleanupNav();cleanup=()=>{};cleanupNav=()=>{};if($('#modal').open)$('#modal').close();
 let path=location.pathname.replace(/\/$/,'')||'/';window.scrollTo(0,0);
 if(REDIRECTS[path]){history.replaceState({},'',REDIRECTS[path]+location.search);path=REDIRECTS[path];}
 const fail=error=>{if(version!==routeVersion)return;if($('#page'))errorView(error);else $('#app').innerHTML=navbar()+`<main class="legal-page" id="main">${empty('Something went wrong',esc(error.message),`<a class="button primary" href="${paths.learn}">Back to Learn</a>`)}</main>`;};
 try{
  if(path==='/'){if(user){history.replaceState({},'',paths.learn);return render();}homepage();return;}
  if(['/about','/privacy','/terms'].includes(path)){legalPage(path.slice(1));return;}
  if(path==='/start'){await learn.startPage();return;}
  if(path.startsWith('/auth/')){const mode=path.split('/')[2];if(['login','forgot-password','reset-password'].includes(mode)){if(user&&mode==='login'){history.replaceState({},'',paths.learn);return render();}authPage(mode);return;}notFound();return;}
  if(needLogin(path))return;
  let m;
  if((m=path.match(/^\/learn\/lesson\/([a-z0-9-]+)$/))){await learn.lessonPage(m[1]);return;}
  if(path==='/practice/challenge'){await practice.challengePage();return;}
  if((m=path.match(/^\/practice\/(strategy|count|decks|truecount|index)$/))){await practice.toolPage(m[1]);return;}
  const tab=path.split('/')[1];
  if(!TABS.some(t=>t[0]===tab)){notFound();return;}
  appShell(tab);
  if(path==='/learn')await learn.learnPage();
  else if(path==='/practice')await practice.hub();
  else if(path==='/practice/simulator')await simulator();
  else if(path==='/track'||path==='/track/bankrolls'){withTabs([['/track','Sessions'],['/track/bankrolls','Bankrolls']],path);if(path==='/track')await resultsPage('results');else await bankrollPage();}
  else if(['/community','/community/directory','/community/messages'].includes(path)){withTabs([['/community','Forum'],['/community/directory','Game Directory'],['/community/messages','Messages']],path);if(path==='/community')await forumPage();else if(path==='/community/directory')await directoryPage();else await messagesPage();}
  else if(path==='/profile')await profilePage();
  else notFound();
 }catch(error){fail(error);}
}
async function boot(){try{configInfo=await api('/api/me');user=configInfo.user;}catch(error){toast('The server could not be reached. Reload to try again.');}await render();}
boot();
